import { memo } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { StatusDot } from "@/shared/ui/feedback/StatusDot";

// Vendored from `./kitChrome` + `./lib/model` (unresolvable here — see plannercomponentspane for the
// same pattern) — the Role shape + RoleDot chrome bit, unchanged logic.
type Role = "primitive" | "composite" | "layout" | "page" | "service";
const ROLE_COLOR: Record<Role, string> = {
  primitive: "var(--info)", composite: "var(--accent)", layout: "var(--violet)", page: "var(--success)", service: "var(--state-wait, var(--accent))",
};
function RoleDot({ role, size = 8 }: { role: Role; size?: number }) {
  return <StatusDot color={ROLE_COLOR[role]} size={size} />;
}

// `NODE_W` vendored verbatim from `./lib/compositionLayout` (a real, readable pure-data module).
const NODE_W = 170;

// `HEALTH_BADGE`/`HealthCategory` vendored from `./lib/graphHealth` — that file could not be read in
// this sandbox (binary/encoding error on `bsc files read`), so this is a best-effort reconstruction from
// context: `componentScan.ts` (readable) confirms HealthCategory includes at least `empty-empty-state` /
// `empty-loading-state`, and that it backs the SAME static graph-health findings this app's own
// `bsc ui doctor` reports (its own comment: "the static analyzeGraphHealth/Rust doctor"). Modeled the
// badge set on doctor's real finding categories accordingly.
type HealthCategory = "orphan" | "duplicate" | "cycle" | "dangling-branch" | "empty-empty-state" | "empty-loading-state";
const HEALTH_BADGE: Record<HealthCategory, { glyph: string; label: string }> = {
  orphan: { glyph: "○", label: "orphan — nothing composes it" },
  duplicate: { glyph: "⧉", label: "duplicate implementation" },
  cycle: { glyph: "↻", label: "composition cycle" },
  "dangling-branch": { glyph: "⌇", label: "dangling branch — unused root" },
  "empty-empty-state": { glyph: "▢", label: "blank in its empty state" },
  "empty-loading-state": { glyph: "▢", label: "blank in its loading state" },
};

// `ComponentBuildStatus` vendored verbatim from `./lib/componentScan` (a real, readable module).
type ComponentBuildStatus =
  | { state: "ok" }
  | { state: "error"; kind: "build" | "runtime"; message: string }
  | { state: "empty"; message: string };

interface ComponentRecord {
  id: string; name: string; role: Role; folder?: string; used: number;
}

export interface ComponentNodeProps {
  c: ComponentRecord;
  x: number;
  y: number;
  selected: boolean;
  related: boolean;
  working: boolean;
  badge?: HealthCategory;
  buildStatus?: ComponentBuildStatus;
  onSelect: (c: ComponentRecord) => void;
}

const SAMPLE_C: ComponentRecord = { id: "c1", name: "GitHubCrossRepoActivity", role: "composite", folder: "github", used: 4 };

export const ComponentNode = memo(function ComponentNode({
  c = SAMPLE_C, x = 40, y = 40, selected = false, related = false, working = false, badge = "orphan", buildStatus, onSelect = () => {},
}: Partial<ComponentNodeProps>) {
  const state = selected ? " on" : related ? " related" : "";
  const buildError = buildStatus?.state === "error"
    ? `Preview ${buildStatus.kind} error — ${buildStatus.message}`
    : null;
  const emptyRender = buildStatus?.state === "empty" ? buildStatus.message : null;
  return (
    <Box
      data-node
      onClick={() => onSelect(c)}
      className={`ds-node${state}${working ? " working" : ""}${badge ? " unhealthy" : ""}`}
      style={{ position: "absolute", left: x, top: y, width: NODE_W }}
    >
      {badge && (
        <Text as="span" className={`ds-health ds-health-${badge}`} title={`${badge} — ${HEALTH_BADGE[badge].label}`}>{HEALTH_BADGE[badge].glyph}</Text>
      )}
      {buildError && (
        <Text as="span" className="ds-buildfail" title={buildError}>✖</Text>
      )}
      {emptyRender && (
        <Text as="span" className="ds-emptyrender" title={emptyRender}>▢</Text>
      )}
      <Box style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 5, minWidth: 0 }}>
        <RoleDot role={c.role} /><Text weight={600} size={13} title={c.name} style={{ flex: 1, minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{c.name}</Text>
      </Box>
      <Box style={{ display: "flex", alignItems: "center", justifyContent: "space-between", minWidth: 0 }}>
        <Text size={10} tone="dim" title={c.folder ? `${c.role} · ${c.folder}` : c.role} style={{ flex: 1, minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{c.role}{c.folder ? <Text as="span" tone="muted"> · {c.folder}</Text> : ""}</Text><Text mono size="xxs" tone="muted" style={{ flexShrink: 0, marginLeft: 6 }}>×{c.used}</Text>
      </Box>
    </Box>
  );
});
